import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum UserRole {
  ADMIN = 'ADMIN',
  RESIDENT = 'RESIDENT'
}

export interface User {
  id: string;
  name: string;
  email: string;
  role: UserRole;
  avatar?: string;
  houseNumber?: string;
}

export interface ServiceRequest {
  id: string;
  residentId: string;
  residentName: string;
  title: string;
  description: string;
  status: 'PENDING' | 'IN_PROGRESS' | 'COMPLETED' | 'CANCELLED';
  createdAt: string;
  category: 'MAINTENANCE' | 'SECURITY' | 'UTILITIES' | 'OTHERS';
  imageUrl?: string;
}

export interface Announcement {
  id: string;
  title: string;
  content: string;
  date: string;
  author: string;
  category: 'URGENT' | 'GENERAL' | 'EVENT';
}

export interface Payment {
  id: string;
  residentId: string;
  amount: number;
  date: string;
  status: 'PAID' | 'PENDING' | 'OVERDUE';
  description: string;
}

import { GoogleGenAI, Type } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const analyzeImage = async (base64Image: string, prompt: string) => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: {
      parts: [
        { inlineData: { data: base64Image, mimeType: 'image/jpeg' } },
        { text: prompt }
      ]
    }
  });
  return response.text;
};

export const chatWithGemini = async (history: { role: 'user' | 'model', message: string }[], newMessage: string) => {
  const ai = getAI();
  const chat = ai.chats.create({
    model: 'gemini-3-pro-preview',
    config: {
      systemInstruction: 'You are an intelligent assistant for Village AIS (Administrative & Information System). Your goal is to help residents with village-related queries, service requests, and general information about their community. Be polite, helpful, and concise.',
    }
  });

  // Sending the message. Note: library uses message string directly
  const response = await chat.sendMessage({ message: newMessage });
  return response.text;
};

export const extractReceiptData = async (base64Image: string) => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: {
      parts: [
        { inlineData: { data: base64Image, mimeType: 'image/jpeg' } },
        { text: 'Extract total amount, date, and vendor from this receipt. Return as JSON.' }
      ]
    },
    config: {
      responseMimeType: 'application/json',
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          amount: { type: Type.NUMBER },
          date: { type: Type.STRING },
          vendor: { type: Type.STRING },
        },
        required: ['amount', 'date', 'vendor']
      }
    }
  });
  return JSON.parse(response.text || '{}');
};

import React, { useState, useEffect } from 'react';
import { HashRouter as Router, Routes, Route, Navigate, Link, useLocation, useNavigate } from 'react-router-dom';
import { 
  LayoutDashboard, 
  Users, 
  CreditCard, 
  ClipboardList, 
  Bell, 
  BarChart3, 
  Settings, 
  LogOut, 
  Menu, 
  X, 
  MessageSquare, 
  User as UserIcon,
  Home,
  PlusCircle,
  History
} from 'lucide-react';
import { User, UserRole } from './types';
import Login from './pages/Login';
import Dashboard from './pages/Dashboard';
import ResidentsList from './pages/Admin/ResidentsList';
import ServiceRequests from './pages/Admin/ServiceRequests';
import Payments from './pages/Admin/Payments';
import Announcements from './pages/Announcements';
import Profile from './pages/Resident/Profile';
import SubmitRequest from './pages/Resident/SubmitRequest';
import ChatSupport from './pages/Resident/ChatSupport';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('village_user');
    return saved ? JSON.parse(saved) : null;
  });

  const handleLogin = (userData: User) => {
    setUser(userData);
    localStorage.setItem('village_user', JSON.stringify(userData));
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('village_user');
  };

  return (
    <Router>
      <Routes>
        <Route path="/login" element={user ? <Navigate to="/dashboard" /> : <Login onLogin={handleLogin} />} />

        <Route element={<MainLayout user={user} onLogout={handleLogout} />}>
          <Route path="/dashboard" element={<ProtectedRoute user={user}><Dashboard user={user!} /></ProtectedRoute>} />

          {/* Admin Routes */}
          <Route path="/admin/residents" element={<ProtectedRoute user={user} role={UserRole.ADMIN}><ResidentsList /></ProtectedRoute>} />
          <Route path="/admin/requests" element={<ProtectedRoute user={user} role={UserRole.ADMIN}><ServiceRequests /></ProtectedRoute>} />
          <Route path="/admin/payments" element={<ProtectedRoute user={user} role={UserRole.ADMIN}><Payments /></ProtectedRoute>} />

          {/* Shared / Common Routes */}
          <Route path="/announcements" element={<ProtectedRoute user={user}><Announcements isAdmin={user?.role === UserRole.ADMIN} /></ProtectedRoute>} />

          {/* Resident Routes */}
          <Route path="/resident/profile" element={<ProtectedRoute user={user} role={UserRole.RESIDENT}><Profile user={user!} /></ProtectedRoute>} />
          <Route path="/resident/submit-request" element={<ProtectedRoute user={user} role={UserRole.RESIDENT}><SubmitRequest user={user!} /></ProtectedRoute>} />
          <Route path="/resident/history" element={<ProtectedRoute user={user} role={UserRole.RESIDENT}><Payments residentId={user?.id} /></ProtectedRoute>} />
          <Route path="/support" element={<ProtectedRoute user={user}><ChatSupport /></ProtectedRoute>} />

          <Route path="/" element={<Navigate to="/dashboard" />} />
        </Route>
      </Routes>
    </Router>
  );
};

const ProtectedRoute: React.FC<{ user: User | null; role?: UserRole; children: React.ReactNode }> = ({ user, role, children }) => {
  if (!user) return <Navigate to="/login" />;
  if (role && user.role !== role) return <Navigate to="/dashboard" />;
  return <>{children}</>;
};

const MainLayout: React.FC<{ user: User | null; onLogout: () => void }> = ({ user, onLogout }) => {
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const location = useLocation();
  const navigate = useNavigate();

  if (!user) return null;

  const adminNav = [
    { name: 'Dashboard', icon: LayoutDashboard, path: '/dashboard' },
    { name: 'Residents', icon: Users, path: '/admin/residents' },
    { name: 'Service Queue', icon: ClipboardList, path: '/admin/requests' },
    { name: 'Payments', icon: CreditCard, path: '/admin/payments' },
    { name: 'Announcements', icon: Bell, path: '/announcements' },
    { name: 'AI Support', icon: MessageSquare, path: '/support' },
  ];

  const residentNav = [
    { name: 'Home', icon: Home, path: '/dashboard' },
    { name: 'Request Service', icon: PlusCircle, path: '/resident/submit-request' },
    { name: 'Payments', icon: History, path: '/resident/history' },
    { name: 'Announcements', icon: Bell, path: '/announcements' },
    { name: 'Profile', icon: UserIcon, path: '/resident/profile' },
    { name: 'AI Assistant', icon: MessageSquare, path: '/support' },
  ];

  const currentNav = user.role === UserRole.ADMIN ? adminNav : residentNav;

  const handleLogoutClick = () => {
    onLogout();
    navigate('/login');
  };

  return (
    <div className="flex flex-col h-screen overflow-hidden">
      {/* Top Header */}
      <header className="bg-white border-b px-4 py-3 flex items-center justify-between sticky top-0 z-50">
        <div className="flex items-center gap-3">
          <button onClick={() => setSidebarOpen(true)} className="md:hidden p-1">
            <Menu className="w-6 h-6 text-gray-600" />
          </button>
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-emerald-600 rounded-lg flex items-center justify-center">
              <span className="text-white font-bold text-sm">V</span>
            </div>
            <h1 className="font-bold text-lg text-emerald-900 hidden sm:block">Village AIS</h1>
          </div>
        </div>

        <div className="flex items-center gap-3">
          <div className="text-right hidden sm:block">
            <p className="text-sm font-medium text-gray-900">{user.name}</p>
            <p className="text-xs text-gray-500 capitalize">{user.role.toLowerCase()}</p>
          </div>
          <div className="w-10 h-10 rounded-full bg-emerald-100 flex items-center justify-center border-2 border-emerald-500 overflow-hidden">
            {user.avatar ? (
              <img src={user.avatar} alt="Avatar" className="w-full h-full object-cover" />
            ) : (
              <UserIcon className="w-6 h-6 text-emerald-600" />
            )}
          </div>
        </div>
      </header>

      <div className="flex flex-1 overflow-hidden">
        {/* Mobile Sidebar Overlay */}
        {sidebarOpen && (
          <div className="fixed inset-0 z-50 md:hidden">
            <div className="absolute inset-0 bg-black/50" onClick={() => setSidebarOpen(false)} />
            <div className="absolute left-0 top-0 bottom-0 w-64 bg-white shadow-xl animate-in slide-in-from-left duration-200">
              <div className="p-4 border-b flex justify-between items-center">
                <span className="font-bold text-emerald-900">Navigation</span>
                <button onClick={() => setSidebarOpen(false)}><X className="w-6 h-6 text-gray-500" /></button>
              </div>
              <nav className="p-4 flex flex-col gap-2">
                {currentNav.map((item) => (
                  <Link
                    key={item.path}
                    to={item.path}
                    onClick={() => setSidebarOpen(false)}
                    className={`flex items-center gap-3 p-3 rounded-lg transition-colors ${
                      location.pathname === item.path ? 'bg-emerald-50 text-emerald-700' : 'text-gray-600 hover:bg-gray-50'
                    }`}
                  >
                    <item.icon className="w-5 h-5" />
                    <span className="font-medium">{item.name}</span>
                  </Link>
                ))}
                <button
                  onClick={handleLogoutClick}
                  className="mt-10 flex items-center gap-3 p-3 text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                >
                  <LogOut className="w-5 h-5" />
                  <span className="font-medium">Sign Out</span>
                </button>
              </nav>
            </div>
          </div>
        )}

        {/* Desktop Sidebar */}
        <aside className="hidden md:flex flex-col w-64 bg-white border-r p-4 gap-2">
          {currentNav.map((item) => (
            <Link
              key={item.path}
              to={item.path}
              className={`flex items-center gap-3 p-3 rounded-lg transition-all ${
                location.pathname === item.path ? 'bg-emerald-600 text-white shadow-md' : 'text-gray-600 hover:bg-emerald-50 hover:text-emerald-600'
              }`}
            >
              <item.icon className="w-5 h-5" />
              <span className="font-medium">{item.name}</span>
            </Link>
          ))}
          <div className="mt-auto pt-4 border-t">
            <button
              onClick={handleLogoutClick}
              className="w-full flex items-center gap-3 p-3 text-gray-600 hover:bg-red-50 hover:text-red-600 rounded-lg transition-colors"
            >
              <LogOut className="w-5 h-5" />
              <span className="font-medium">Sign Out</span>
            </button>
          </div>
        </aside>

        {/* Main Content Area */}
        <main className="flex-1 overflow-y-auto bg-gray-50">
          <div className="p-4 md:p-8 max-w-7xl mx-auto">
            <React.Suspense fallback={<div className="flex items-center justify-center h-full">Loading...</div>}>
              <Routes>
                <Route path="/dashboard" element={<Dashboard user={user} />} />
                <Route path="/admin/residents" element={<ResidentsList />} />
                <Route path="/admin/requests" element={<ServiceRequests />} />
                <Route path="/admin/payments" element={<Payments />} />
                <Route path="/announcements" element={<Announcements isAdmin={user.role === UserRole.ADMIN} />} />
                <Route path="/resident/profile" element={<Profile user={user} />} />
                <Route path="/resident/submit-request" element={<SubmitRequest user={user} />} />
                <Route path="/resident/history" element={<Payments residentId={user.id} />} />
                <Route path="/support" element={<ChatSupport />} />
              </Routes>
            </React.Suspense>
          </div>
        </main>
      </div>

      {/* Mobile Bottom Navigation (only for residents for quick access) */}
      {user.role === UserRole.RESIDENT && (
        <nav className="md:hidden bg-white border-t flex justify-around py-3 px-2 sticky bottom-0 z-50">
          {residentNav.slice(0, 4).map((item) => (
            <Link
              key={item.path}
              to={item.path}
              className={`flex flex-col items-center gap-1 ${
                location.pathname === item.path ? 'text-emerald-600' : 'text-gray-400'
              }`}
            >
              <item.icon className="w-6 h-6" />
              <span className="text-[10px] font-medium">{item.name}</span>
            </Link>
          ))}
        </nav>
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
