const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('village_user');
    return saved ? JSON.parse(saved) : null;
  });

  const handleLogin = (userData: User) => {
    setUser(userData);
    localStorage.setItem('village_user', JSON.stringify(userData));
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('village_user');
  };

  return (
    <Router>
      <Routes>
        <Route path="/login" element={user ? <Navigate to="/dashboard" /> : <Login onLogin={handleLogin} />} />

        {/* Protected Layout Route */}
        <Route 
          element={user ? <MainLayout user={user} onLogout={handleLogout} /> : <Navigate to="/login" />}
        >
          <Route path="/dashboard" element={<Dashboard user={user!} />} />

          {/* Admin Routes */}
          <Route 
            path="/admin/residents" 
            element={user?.role === UserRole.ADMIN ? <ResidentsList /> : <Navigate to="/dashboard" />} 
          />
          <Route 
            path="/admin/requests" 
            element={user?.role === UserRole.ADMIN ? <ServiceRequests /> : <Navigate to="/dashboard" />} 
          />
          <Route 
            path="/admin/payments" 
            element={user?.role === UserRole.ADMIN ? <Payments /> : <Navigate to="/dashboard" />} 
          />

          {/* Shared Routes */}
          <Route path="/announcements" element={<Announcements isAdmin={user?.role === UserRole.ADMIN} />} />
          <Route path="/emergency" element={<EmergencyContacts isAdmin={user?.role === UserRole.ADMIN} />} />

          {/* Resident Routes */}
          <Route 
            path="/resident/profile" 
            element={user?.role === UserRole.RESIDENT ? <Profile user={user!} /> : <Navigate to="/dashboard" />} 
          />
          <Route 
            path="/resident/submit-request" 
            element={user?.role === UserRole.RESIDENT ? <SubmitRequest user={user!} /> : <Navigate to="/dashboard" />} 
          />
          <Route 
            path="/resident/history" 
            element={user?.role === UserRole.RESIDENT ? <Payments residentId={user?.id} /> : <Navigate to="/dashboard" />} 
          />

          <Route path="/" element={<Navigate to="/dashboard" />} />
        </Route>
      </Routes>
    </Router>
  );
};

