          <div className="text-right hidden sm:block">
            <p className="text-sm font-bold text-black">{user.name}</p>
            <p className="text-xs text-gray-500 font-bold uppercase">{user.role}</p>
          </div>
          <div className="w-10 h-10 rounded-full bg-blue-50 flex items-center justify-center border-2 border-[#0068B6] overflow-hidden">
            {user.avatar ? (
              <img src={user.avatar} alt="Avatar" className="w-full h-full object-cover" />
            ) : (
              <UserIcon className="w-6 h-6 text-[#0068B6]" />
            )}
          </div>
        </div>
      </header>

      <div className="flex flex-1 overflow-hidden">
        {/* Mobile Sidebar Overlay */}
        {sidebarOpen && (
          <div className="fixed inset-0 z-50 md:hidden">
            <div className="absolute inset-0 bg-black/50" onClick={() => setSidebarOpen(false)} />
            <div className="absolute left-0 top-0 bottom-0 w-64 bg-white shadow-xl animate-in slide-in-from-left duration-200">
              <div className="p-4 border-b flex justify-between items-center">
                <span className="font-bold text-[#003067]">Navigation</span>
                <button onClick={() => setSidebarOpen(false)}><X className="w-6 h-6 text-gray-500" /></button>
              </div>
              <nav className="p-4 flex flex-col gap-2">
                {currentNav.map((item) => (
                  <Link
                    key={item.path}
                    to={item.path}
                    onClick={() => setSidebarOpen(false)}
                    className={`flex items-center gap-3 p-3 rounded-lg transition-colors ${
                      location.pathname === item.path ? 'bg-[#0068B6]/10 text-[#0068B6]' : 'text-black font-bold hover:bg-gray-50'
                    }`}
                  >
                    <item.icon className="w-5 h-5" />
                    <span className="font-bold">{item.name}</span>
                  </Link>
                ))}
                <button
                  onClick={handleLogoutClick}
                  className="mt-10 flex items-center gap-3 p-3 text-red-600 hover:bg-red-50 rounded-lg transition-colors font-bold"
                >
                  <LogOut className="w-5 h-5" />
                  <span>Sign Out</span>
                </button>
              </nav>
            </div>
          </div>
        )}

        {/* Desktop Sidebar */}
        <aside className="hidden md:flex flex-col w-64 bg-[#003067] p-4 gap-2">
          {currentNav.map((item) => (
            <Link
              key={item.path}
              to={item.path}
              className={`flex items-center gap-3 p-3 rounded-lg transition-all ${
                location.pathname === item.path ? 'bg-[#0068B6] text-white shadow-md' : 'text-blue-100/70 hover:bg-[#0068B6]/20 hover:text-white'
              }`}
            >
              <item.icon className="w-5 h-5" />
              <span className="font-bold">{item.name}</span>
            </Link>
          ))}
          <div className="mt-auto pt-4 border-t border-blue-900/50">
            <button
              onClick={handleLogoutClick}
              className="w-full flex items-center gap-3 p-3 text-blue-100/70 hover:bg-red-500/10 hover:text-red-400 rounded-lg transition-colors font-bold"
            >
              <LogOut className="w-5 h-5" />
              <span>Sign Out</span>
            </button>
          </div>
        </aside>

        {/* Main Content Area */}
        <main className="flex-1 overflow-y-auto bg-[#f0f4f8]">
          <div className="p-4 md:p-8 max-w-7xl mx-auto">
            <React.Suspense fallback={<div className="flex items-center justify-center h-full text-[#003067] font-bold">Loading...</div>}>
              <Outlet />
            </React.Suspense>
          </div>
        </main>
      </div>

      {/* Mobile Bottom Navigation */}
      {user.role === UserRole.RESIDENT && (
        <nav className="md:hidden bg-white border-t flex justify-around py-3 px-2 sticky bottom-0 z-50">
          {residentNav.slice(0, 5).map((item) => (
            <Link
              key={item.path}
              to={item.path}
              className={`flex flex-col items-center gap-1 ${
                location.pathname === item.path ? 'text-[#0068B6]' : 'text-gray-400'
              }`}
            >
              <item.icon className="w-6 h-6" />
              <span className="text-[10px] font-bold uppercase">{item.name.split(' ')[0]}</span>
            </Link>
          ))}
        </nav>
      )}
    </div>
  );
};

export default App;

